import FreeCAD
import Part

# Open the document
doc = FreeCAD.open("/home/user/Unnamed.FCStd")
print(f"Document opened: {doc.Name}")

# Get the sketch
sketch = doc.getObject("Ellipse_Sketch")
if sketch:
    print(f"\nSketch found: {sketch.Name}")
    print(f"Number of geometries: {len(sketch.Geometry)}")

    for i, geom in enumerate(sketch.Geometry):
        print(f"\nGeometry {i}:")
        print(f"  Type: {type(geom).__name__}")

        if hasattr(geom, 'Center'):
            print(f"  Center: {geom.Center}")
        if hasattr(geom, 'MajorRadius'):
            print(f"  MajorRadius: {geom.MajorRadius}")
        if hasattr(geom, 'MinorRadius'):
            print(f"  MinorRadius: {geom.MinorRadius}")
        if hasattr(geom, 'StartPoint'):
            print(f"  StartPoint: {geom.StartPoint}")
        if hasattr(geom, 'EndPoint'):
            print(f"  EndPoint: {geom.EndPoint}")
        if hasattr(geom, 'FirstParameter'):
            print(f"  FirstParameter: {geom.FirstParameter}")
        if hasattr(geom, 'LastParameter'):
            print(f"  LastParameter: {geom.LastParameter}")
        if hasattr(geom, 'ConstructionMode'):
            print(f"  ConstructionMode: {geom.ConstructionMode}")
else:
    print("ERROR: Sketch not found!")

# Recompute to ensure everything is valid
try:
    doc.recompute()
    print("\nRecompute successful!")
except Exception as e:
    print(f"\nRecompute error: {e}")

# Check if the shape is valid
if sketch:
    try:
        shape = sketch.Shape
        print(f"\nSketch shape: {shape}")
        print(f"Shape type: {type(shape)}")
        print(f"Number of edges: {len(shape.Edges)}")
        print(f"Number of vertices: {len(shape.Vertices)}")
    except Exception as e:
        print(f"Error getting shape: {e}")

# Save again to ensure it's properly saved
doc.saveAs("/home/user/Unnamed.FCStd")
print("\nDocument re-saved successfully")
